// Code node: "Score & Estimate" (Run Once for All Items)
const RATE = 45; // USD per hour

const BASE_HOURS = {
  'AI Agent / Chatbot': [30, 60],
  'Workflow Automation (n8n / Zapier / Make)': [10, 30],
  'RAG Knowledge Base': [25, 50],
  'Voice AI Agent': [30, 60],
  'Web Application': [60, 140],
  'Mobile App': [80, 180],
  'Other': [20, 60],
};

const FEATURE_HOURS = {
  'CRM integration': 8,
  'Payments': 10,
  'User accounts & roles': 12,
  'Admin dashboard': 16,
  'Third-party API integrations': 10,
  'AI / LLM features': 14,
  'Reporting & analytics': 12,
  'Multi-language': 8,
};

const BUDGET_SCORE = {
  'Under $500': 0,
  '$500 – $2,000': 15,
  '$2,000 – $5,000': 25,
  '$5,000 – $15,000': 35,
  '$15,000+': 40,
};
const BUDGET_MAX = {
  'Under $500': 500,
  '$500 – $2,000': 2000,
  '$2,000 – $5,000': 5000,
  '$5,000 – $15,000': 15000,
  '$15,000+': Infinity,
};

const TIMELINE_SCORE = {
  'ASAP (under 2 weeks)': 20,
  'Within 1 month': 20,
  '2 – 3 months': 12,
  'Flexible': 5,
};

const toList = (v) => (Array.isArray(v) ? v : v ? String(v).split(',').map((s) => s.trim()).filter(Boolean) : []);
const roundTo = (n, step) => Math.round(n / step) * step;
const money = (n) => '$' + n.toLocaleString('en-US');

const out = [];
for (const item of $input.all()) {
  const f = item.json;
  const type = f['Project Type'] || 'Other';
  const features = toList(f['Key Features']);
  const budget = f['Budget'] || 'Under $500';
  const timeline = f['Timeline'] || 'Flexible';
  const description = String(f['Project Description'] || '').trim();
  const email = String(f['Work Email'] || '').trim().toLowerCase();

  const [minBase, maxBase] = BASE_HOURS[type] || BASE_HOURS['Other'];
  const featureHours = features.reduce((sum, x) => sum + (FEATURE_HOURS[x] || 6), 0);
  const rush = timeline.startsWith('ASAP') ? 1.15 : 1;
  const hoursMin = Math.round((minBase + featureHours * 0.8) * rush);
  const hoursMax = Math.round((maxBase + featureHours * 1.2) * rush);
  const priceMin = roundTo(hoursMin * RATE, 50);
  const priceMax = roundTo(hoursMax * RATE, 50);

  // Lead score (0-100)
  const freeDomains = ['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com', 'icloud.com', 'proton.me', 'protonmail.com'];
  const domain = email.split('@')[1] || '';
  let score = 0;
  score += BUDGET_SCORE[budget] ?? 0;
  score += TIMELINE_SCORE[timeline] ?? 5;
  score += description.length >= 300 ? 20 : description.length >= 120 ? 12 : description.length >= 40 ? 6 : 0;
  score += domain && !freeDomains.includes(domain) ? 10 : 0;
  score += f['Company'] ? 5 : 0;
  score += features.length >= 2 ? 5 : 0;
  score = Math.min(100, score);

  const budgetFits = (BUDGET_MAX[budget] ?? 0) >= priceMin;
  const tier = score >= 70 ? 'Hot' : score >= 45 ? 'Warm' : 'Cold';
  const nextStep =
    tier === 'Hot'
      ? 'Reply within 2 hours and offer a discovery call.'
      : tier === 'Warm'
      ? 'Reply same day with 2-3 clarifying questions.'
      : 'Send the standard info pack and packaged services.';

  out.push({
    json: {
      id: 'L-' + Date.now().toString(36).toUpperCase(),
      submittedAt: new Date().toISOString(),
      name: f['Full Name'] || '',
      email,
      company: f['Company'] || '',
      projectType: type,
      features,
      budget,
      timeline,
      description,
      hoursMin,
      hoursMax,
      priceMin,
      priceMax,
      priceRange: `${money(priceMin)} – ${money(priceMax)}`,
      budgetFits,
      score,
      tier,
      nextStep,
    },
  });
}
return out;

// Code node: "Save to Lead Store" (Run Once for All Items)
// Stores leads in this workflow's static data (persists for production/active runs only).
const store = $getWorkflowStaticData('global');
store.leads = store.leads || [];
for (const item of $input.all()) {
  store.leads.unshift(item.json);
}
store.leads = store.leads.slice(0, 500); // keep the latest 500
return $input.all();

