// Code node: "Build Dashboard HTML" (Run Once for All Items)
const store = $getWorkflowStaticData('global');
const leads = store.leads || [];
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const count = (t) => leads.filter((l) => l.tier === t).length;
const pipeline = leads.reduce((s, l) => s + (l.priceMax || 0), 0);

const rows = leads
  .map(
    (l) => `<tr>
  <td>${esc(new Date(l.submittedAt).toISOString().slice(0, 16).replace('T', ' '))}</td>
  <td><strong>${esc(l.name)}</strong><br><span class="muted">${esc(l.company)}</span></td>
  <td>${esc(l.email)}</td>
  <td>${esc(l.projectType)}</td>
  <td>${esc(l.budget)}${l.budgetFits ? '' : ' <span class="warn">below estimate</span>'}</td>
  <td>${esc(l.priceRange)}<br><span class="muted">${l.hoursMin}–${l.hoursMax} h</span></td>
  <td><span class="tag ${esc(l.tier).toLowerCase()}">${esc(l.tier)} · ${l.score}</span></td>
  <td class="muted">${esc(l.nextStep)}</td>
</tr>`
  )
  .join('');

const html = `<!doctype html><html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex">
<title>Lead Dashboard</title>
<style>
:root{--bg:#f6f7f9;--card:#fff;--ink:#16181d;--muted:#6b7280;--line:#e5e7eb;--hot:#dc2626;--warm:#d97706;--cold:#2563eb}
@media (prefers-color-scheme:dark){:root{--bg:#0f1115;--card:#171a21;--ink:#e8eaed;--muted:#9aa1ad;--line:#2a2f3a}}
*{box-sizing:border-box}body{margin:0;font:14px/1.45 system-ui,-apple-system,Segoe UI,Roboto,sans-serif;background:var(--bg);color:var(--ink)}
main{max-width:1200px;margin:0 auto;padding:24px 16px}h1{font-size:22px;margin:0 0 4px}
.kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:12px;margin:18px 0}
.kpi{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:14px}.kpi b{display:block;font-size:22px}
.wrap{overflow-x:auto;background:var(--card);border:1px solid var(--line);border-radius:10px}
table{width:100%;border-collapse:collapse;min-width:900px}th,td{padding:10px 12px;border-bottom:1px solid var(--line);text-align:left;vertical-align:top}
th{font-size:12px;text-transform:uppercase;letter-spacing:.04em;color:var(--muted)}.muted{color:var(--muted);font-size:12px}
.tag{padding:2px 8px;border-radius:999px;font-weight:600;font-size:12px;color:#fff}.hot{background:var(--hot)}.warm{background:var(--warm)}.cold{background:var(--cold)}
.warn{color:var(--warm);font-size:12px}.empty{padding:40px;text-align:center;color:var(--muted)}
</style></head><body><main>
<h1>Project Inquiry Dashboard</h1><div class="muted">Auto-scored leads from the intake form · updated ${esc(new Date().toISOString().slice(0, 16).replace('T', ' '))} UTC</div>
<section class="kpis">
<div class="kpi"><span class="muted">Total inquiries</span><b>${leads.length}</b></div>
<div class="kpi"><span class="muted">Hot</span><b style="color:var(--hot)">${count('Hot')}</b></div>
<div class="kpi"><span class="muted">Warm</span><b style="color:var(--warm)">${count('Warm')}</b></div>
<div class="kpi"><span class="muted">Cold</span><b style="color:var(--cold)">${count('Cold')}</b></div>
<div class="kpi"><span class="muted">Pipeline (max estimate)</span><b>$${pipeline.toLocaleString('en-US')}</b></div>
</section>
<div class="wrap">${
  leads.length
    ? `<table><thead><tr><th>Received (UTC)</th><th>Client</th><th>Email</th><th>Project</th><th>Budget</th><th>Estimate</th><th>Score</th><th>Next step</th></tr></thead><tbody>${rows}</tbody></table>`
    : '<div class="empty">No inquiries yet. Submit the intake form to see leads appear here.</div>'
}</div></main></body></html>`;

return [{ json: { html } }];
